#!/usr/bin/env bash
# Shared environment for a saved Gait Fidelity run. Source from another script.
set -euo pipefail
gf_code_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd -P)"
gf_load_session() {
  local work="$1"
  [[ -f "$work/session.env" ]] || {
    printf 'Saved session is missing: %s/session.env\nRun setup first.\n' "$work" >&2
    return 1
  }
  # Generated by the initializer from the user's own configuration.
  source "$work/session.env"
  : "${GF_ROOT:?Saved session must define GF_ROOT}"
  : "${GF_WORK:?Saved session must define GF_WORK}"
  : "${GF_PYTHON:?Saved session must define GF_PYTHON}"
  [[ -x "$GF_PYTHON" ]] || { printf 'Interpreter is unavailable: %s\n' "$GF_PYTHON" >&2; return 1; }
  [[ -d "$GF_ROOT/src/gavd6_sjepa/research_directions/gait_fidelity" ]] || {
    printf 'Saved source release is unavailable: %s\n' "$GF_ROOT" >&2; return 1;
  }
  export PYTHONPATH="$GF_ROOT/src"
  export PYTHONNOUSERSITE=1 PYOPENGL_PLATFORM=egl
  export OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 OPENBLAS_NUM_THREADS=4
  export CUBLAS_WORKSPACE_CONFIG=:4096:8
  cd "$GF_ROOT"
}
